import { createFileRoute } from "@tanstack/react-router";
import { requireProjectAccess } from "@/lib/project-access";

function generateHookCode(
  hook: { type: string; name: string; entity: string; code: string },
  _entityName: string
): string {
  const { type, name, entity, code } = hook;

  let hookCode = `/**
 * ${type} Hook: ${name}
 *
 * Hook Type: ${type}
 * Entity: ${entity}
 *
 * This hook is executed ${type.startsWith("before") ? "before" : type.startsWith("after") ? "after" : "during"} ${entity} entity operation.
 *
 * @generated by Hook Code Generator
 */

`;

  const paramName = type.startsWith("before") ? "data" : "result";

  if (type.startsWith("before")) {
    hookCode += `export async function ${name}${entity}(
  ${paramName}: any
): Promise<any> {
  console.log('[${type}:${name}]', { entity: '${entity}' });

`;
  } else if (type.startsWith("after")) {
    hookCode += `export async function ${name}${entity}(
  ${paramName}: any
): Promise<void> {
  console.log('[${type}:${name}]', { entity: '${entity}' });

`;
  } else if (type === "customValidate") {
    hookCode += `export async function ${name}${entity}(
  data: any
): Promise<{ valid: boolean; errors?: string[] }> {
  console.log('[${type}:${name}]', { entity: '${entity}' });

`;
  }

  if (code?.trim()) {
    const indentedCode = code
      .split("\n")
      .map((line: string) => `  ${line}`)
      .join("\n");
    hookCode += `${indentedCode}\n`;
  } else {
    hookCode += `  // TODO: Implement ${name} logic for ${entity}
  // Your code here

`;
  }

  if (type.startsWith("before")) {
    hookCode += `  return ${paramName};
`;
  } else if (type === "customValidate") {
    hookCode += `  return {
    valid: true,
  };
`;
  }

  hookCode += `}\n`;
  return hookCode;
}

export const Route = createFileRoute("/api/projects/$id/workflows/$serviceName/generate")({
  server: {
    handlers: {
      POST: async ({ request, params }) => {
        // Writes hook sources into the project's generated output.
        const access = await requireProjectAccess(request, params.id as string, "read_write");
        if (access.response) return access.response;

        try {
          const projectId = params.id as string;
          const serviceName = params.serviceName as string;

          const body = await request.json();
          const { hooks } = body;

          if (!hooks || !Array.isArray(hooks) || hooks.length === 0) {
            return new Response(
              JSON.stringify({
                success: false,
                error: "No hooks found to generate code",
              }),
              {
                status: 400,
                headers: { "Content-Type": "application/json" },
              }
            );
          }

          const entityName = serviceName.replace("Service", "");
          if (
            !/^[a-zA-Z0-9_-]+$/.test(entityName) ||
            hooks.some(
              (hook: { type: string; name: string }) =>
                !/^[a-zA-Z0-9_-]+$/.test(hook.type) || !/^[a-zA-Z0-9_-]+$/.test(hook.name)
            )
          )
            return Response.json({ error: "Invalid hook name" }, { status: 400 });
          const sources: Record<string, string> = {};
          const generatedFiles = await Promise.all(
            hooks.map(
              async (hook: { type: string; name: string; entity: string; code: string }) => {
                const code = generateHookCode(hook, entityName);
                const fileName = `${hook.type}.${hook.name}.ts`;
                sources[`src/modules/${entityName.toLowerCase()}/hooks/${fileName}`] = code;

                return {
                  fileName,
                  hookType: hook.type,
                  hookName: hook.name,
                  code,
                };
              }
            )
          );

          let indexCode = `/**
 * Hook Exports for ${entityName}
 *
 * This file exports all hook functions for ${entityName}.
 * Hooks are dynamically loaded at runtime.
 *
 * @generated
 */

`;

          hooks.forEach((hook: { name: string; type: string }) => {
            indexCode += `export { ${hook.name}${entityName} as ${hook.name} } from './${hook.type}.${hook.name}';\n`;
          });

          sources[`src/modules/${entityName.toLowerCase()}/hooks/index.ts`] = indexCode;
          const { saveProjectFiles } = await import("@/lib/server/project-repository");
          await saveProjectFiles(projectId, access.user.id, sources, body.requestId);

          return new Response(
            JSON.stringify({
              success: true,
              files: generatedFiles,
              hooksCount: hooks.length,
              message: `Generated ${hooks.length} hook files`,
            }),
            {
              headers: { "Content-Type": "application/json" },
            }
          );
        } catch (error) {
          console.error("Code generation error:", error);
          return new Response(
            JSON.stringify({
              success: false,
              error: error instanceof Error ? error.message : "Failed to generate code",
            }),
            {
              status: 500,
              headers: { "Content-Type": "application/json" },
            }
          );
        }
      },

      GET: async ({ request, params }) => {
        const access = await requireProjectAccess(request, params.id as string);
        if (access.response) return access.response;

        try {
          const serviceName = params.serviceName as string;
          const entityName = (serviceName as string).replace("Service", "");

          return new Response(
            JSON.stringify({
              success: true,
              serviceName,
              entityName,
              supportedHooks: [
                "beforeCreate",
                "afterCreate",
                "beforeUpdate",
                "afterUpdate",
                "beforeDelete",
                "afterDelete",
                "beforeQuery",
                "afterQuery",
                "customValidate",
                "beforeRead",
                "afterRead",
                "beforeList",
                "afterList",
              ],
              outputFormat: "typescript",
              fileStructure: `${entityName.toLowerCase()}/hooks/{hookType}.{hookName}.ts`,
            }),
            {
              headers: { "Content-Type": "application/json" },
            }
          );
        } catch (error) {
          console.error("Error getting generation info:", error);
          return new Response(
            JSON.stringify({
              success: false,
              error: error instanceof Error ? error.message : "Failed to get generation info",
            }),
            {
              status: 500,
              headers: { "Content-Type": "application/json" },
            }
          );
        }
      },
    },
  },
});
